CREATE TABLE [dbo].[mcaPlanMarcacion](	  [country_id] SMALLINT NOT NULL	, [provedor_id] SMALLINT NOT NULL	, [protocolo_id] SMALLINT NOT NULL	, [tipoLlamada_id] SMALLINT NOT NULL	, [prefijo] VARCHAR(15) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [longitud] VARCHAR(15) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, CONSTRAINT [PK_mcaPlanMarcacion] PRIMARY KEY ([country_id] ASC, [provedor_id] ASC, [protocolo_id] ASC, [tipoLlamada_id] ASC))